B.cwh=new A.K(B.vz,["Problema de conex\xe3o da grava\xe7\xe3o","Esta \xe9 uma sess\xe3o de grava\xe7\xe3o do dispositivo, mas o canal de conex\xe3o ainda n\xe3o foi recuperado, ent\xe3o a grava\xe7\xe3o ainda n\xe3o pode ser encerrada. Volte \xe0 lista e aguarde o dispositivo reconectar, ou reconecte-o pela p\xe1gina do dispositivo antes de encerrar.","Permiss\xe3o de microfone necess\xe1ria","A grava\xe7\xe3o em tempo real precisa de acesso ao microfone. Ative a permiss\xe3o de microfone nas configura\xe7\xf5es do sistema antes de continuar.","N\xe3o foi poss\xedvel iniciar o servi\xe7o da p\xe1gina de grava\xe7\xe3o","Marcando...","Marcado","Depura\xe7\xe3o de grava\xe7\xe3o","Dura\xe7\xe3o da grava\xe7\xe3o","Estado da grava\xe7\xe3o: {state}","N\xe3o iniciada","Gravando","Pausada","Parada","Idioma de origem","Idioma de destino (opcional)","Tradu\xe7\xe3o","Conex\xe3o ASR: {state}","Arquivo de \xe1udio: {path}","Foto mais recente: {path}","Fotos capturadas: {count}","Diagn\xf3stico: {message}","(Nenhum)","Ainda n\xe3o h\xe1 transcri\xe7\xe3o","Ainda n\xe3o h\xe1 agenda em tempo real","Transcri\xe7\xe3o em tempo real (par\xe1grafos)","Falante sem r\xf3tulo","Agenda de IA","Agenda n\xba {seq}","Nenhum cliente de rede injetado. Executando em modo mock local.","Sem incremento","{count} itens obtidos","Desconhecido","Gerando","Sucesso","Falhou","Sem conte\xfado","Conclu\xeddo","Imagem atual: captura original","Imagem atual: arquivo editado","|  {message}","Status da sincroniza\xe7\xe3o: {state}  recordId={recordId}  seq={seq}{message}"],t.w)
B.cwi=new A.K(B.vz,["Probl\xe8me de connexion d\u2019enregistrement","Il s\u2019agit d\u2019une session d\u2019enregistrement sur appareil, mais le canal de connexion n\u2019est pas encore r\xe9tabli. L\u2019enregistrement ne peut donc pas encore \xeatre termin\xe9. Revenez \xe0 la liste et attendez la reconnexion de l\u2019appareil, ou reconnectez-le depuis la page de l\u2019appareil avant de terminer.","Autorisation du micro requise","L\u2019enregistrement en temps r\xe9el n\xe9cessite l\u2019acc\xe8s au micro. Activez l\u2019autorisation du micro dans les r\xe9glages syst\xe8me avant de continuer.","Impossible de d\xe9marrer le service de la page d\u2019enregistrement","Marquage en cours...","Marqu\xe9","D\xe9bogage d\u2019enregistrement","Dur\xe9e d\u2019enregistrement","\xc9tat : {state}","Non d\xe9marr\xe9","Enregistrement","En pause","Arr\xeat\xe9","Langue source","Langue cible (facultatif)","Traduction","Connexion ASR : {state}","Fichier audio : {path}","Derni\xe8re photo : {path}","Photos captur\xe9es : {count}","Diagnostic : {message}","(Aucun)","Aucune transcription pour le moment","Aucun agenda temps r\xe9el pour le moment","Transcription en temps r\xe9el (paragraphes)","Intervenant sans \xe9tiquette","Agenda IA","Agenda n\xb0 {seq}","Aucun client r\xe9seau inject\xe9. Ex\xe9cution en mode mock local.","Aucun incr\xe9ment","{count} \xe9l\xe9ments r\xe9cup\xe9r\xe9s","Inconnu","G\xe9n\xe9ration","Succ\xe8s","\xc9chec","Aucun contenu","Termin\xe9","Image actuelle : capture originale","Image actuelle : fichier modifi\xe9","|  {message}","\xc9tat de synchro : {state}  recordId={recordId}  seq={seq}{message}"],t.w)
