B.cD6=new A.eo([B.ex,"\u5bc6\u7801\u987b\u4e3a 8-20 \u4f4d\uff0c\u4e14\u540c\u65f6\u5305\u542b\u5b57\u6bcd\u548c\u6570\u5b57\uff08\u533a\u5206\u5927\u5c0f\u5199\uff09",B.i1,"\u5bc6\u78bc\u9808\u70ba 8-20 \u4f4d\uff0c\u4e14\u540c\u6642\u5305\u542b\u5b57\u6bcd\u548c\u6578\u5b57\uff08\u5340\u5206\u5927\u5c0f\u5beb\uff09",B.kj,"Password must be 8\u201320 characters and contain both letters and digits (case-sensitive)",B.iw,"\u30d1\u30b9\u30ef\u30fc\u30c9\u306f8\u301c20\u6587\u5b57\u3067\u3001\u82f1\u5b57\u3068\u6570\u5b57\u306e\u4e21\u65b9\u3092\u542b\u3081\u3066\u304f\u3060\u3055\u3044\uff08\u5927\u6587\u5b57\u30fb\u5c0f\u6587\u5b57\u3092\u533a\u5225\uff09",B.oj,"\ube44\ubc00\ubc88\ud638\ub294 8~20\uc790\uc774\uba70 \uc601\ubb38\uacfc \uc22b\uc790\ub97c \ubaa8\ub450 \ud3ec\ud568\ud574\uc57c \ud569\ub2c8\ub2e4(\ub300\uc18c\ubb38\uc790 \uad6c\ubd84)",B.uy,"La contrase\xf1a debe tener entre 8 y 20 caracteres e incluir letras y n\xfameros (distingue may\xfasculas y min\xfasculas)",B.uz,"Le mot de passe doit contenir 8 \xe0 20 caract\xe8res, avec des lettres et des chiffres (majuscules et minuscules distingu\xe9es)",B.yQ,"Das Passwort muss 8\u201320 Zeichen lang sein und Buchstaben und Ziffern enthalten (Gro\xdf-/Kleinschreibung beachten)",B.CC,"A senha deve ter de 8 a 20 caracteres e conter letras e n\xfameros (diferencia mai\xfasculas de min\xfasculas)",B.CD,"\u041f\u0430\u0440\u043e\u043b\u044c \u0434\u043e\u043b\u0436\u0435\u043d \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043e\u0442 8 \u0434\u043e 20 \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0431\u0443\u043a\u0432\u044b \u0438 \u0446\u0438\u0444\u0440\u044b (\u0441 \u0443\u0447\u0435\u0442\u043e\u043c \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430)",B.CE,"Kata sandi harus terdiri dari 8\u201320 karakter dan mengandung huruf serta angka (peka huruf besar/kecil)"],t.T7)
